import json
import sys

from framework_evidence import run_tool


def main():
    argv = ["nmap", "-n", "-Pn", "-p-", "-sV", "192.168.2.5"]
    try:
        result = run_tool(argv)
        print(json.dumps(result, sort_keys=True, default=str))
    except Exception as exc:
        print(json.dumps({
            "evidence_version": 1,
            "tool_runs": [{
                "command": argv,
                "status": "error",
                "error": f"{type(exc).__name__}: {exc}"
            }]
        }, sort_keys=True))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

