import json
import sys

command = ["nmap", "-sU", "--top-ports", "100", "-sV", "-n", "192.168.2.5"]

try:
    import framework_evidence
    result = framework_evidence.run_tool(command)
    if isinstance(result, str):
        # Preserve an already-serialized helper envelope without summarizing it.
        try:
            parsed = json.loads(result)
        except json.JSONDecodeError:
            print(result)
        else:
            print(json.dumps(parsed, ensure_ascii=False))
    else:
        print(json.dumps(result, ensure_ascii=False, default=str))
except Exception as exc:
    # A helper or execution error is evidence of failure to obtain a scan result,
    # not evidence about the target's UDP ports.
    print(json.dumps({
        "command": command,
        "status": "error",
        "error_type": type(exc).__name__,
        "error": str(exc),
        "coverage": "No UDP port coverage established; scan result unavailable."
    }, ensure_ascii=False))
    sys.exit(1)

